30→    if (customerData.length > 0) {
31→      console.log(
32→        `[GDPR] Data request for ${customerEmail} at ${shop}:`,
33→        JSON.stringify(customerData),
34→      );
35→    }
36→  }
37→
38→  return new Response();
39→};
