    fd.set("zipCode", editZip);
    fd.set("label", editLabel);
    fd.set("zone", editZone);
    fd.set("message", editMessage);
    fd.set("eta", editEta);
    fd.set("type", editType);
    fd.set("isActive", String(editIsActive));
