            </Text>
            <TextField
              label="CSV data"
              labelHidden
              value={csvText}
              onChange={setCsvText}
              multiline={6}
              placeholder="10001, Manhattan, allowed, Delivery available!, 2-3 days"
              autoComplete="off"
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Range Import Modal */}
      <Modal
        open={rangeModalOpen}
        onClose={() => {
          setRangeModalOpen(false);
          setRangeStart("");
          setRangeEnd("");
          setRangeZone("");
          setRangeType("allowed");
          setRangeMessage("");
          setRangeEta("");
        }}
        title="Import ZIP Code Range"
        primaryAction={{
          content: isRangeLoading ? "Importing..." : "Import Range",
          onAction: handleRangeImport,
          loading: isRangeLoading,
          disabled: !rangeStart.trim() || !rangeEnd.trim(),
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setRangeModalOpen(false);
              setRangeStart("");
              setRangeEnd("");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {rangeResult && (
              <Banner tone={"error" in rangeResult ? "critical" : "success"}>
                {"error" in rangeResult ? (
                  <Text as="p">{(rangeResult as unknown as { error: string }).error}</Text>
                ) : (
                  <Text as="p">
                    Imported <strong>{rangeResult.imported as number}</strong> zip codes
                    ({rangeResult.total as number} in range).
                  </Text>
                )}
              </Banner>
            )}
            <Text as="p" variant="bodyMd">
              Enter a numeric ZIP code range to bulk-import up to 500 zip codes at once.
              Only 5-digit US ZIP codes are supported.
            </Text>
            <InlineGrid columns={2} gap="300">
              <TextField
                label="Start ZIP"
                value={rangeStart}
                onChange={setRangeStart}
                placeholder="10001"
                autoComplete="off"
                maxLength={5}
              />
              <TextField
                label="End ZIP"
                value={rangeEnd}
                onChange={setRangeEnd}
                placeholder="10099"
                autoComplete="off"
                maxLength={5}
              />
            </InlineGrid>
            <Select
              label="Status"
              options={typeOptions}
              value={rangeType}
              onChange={setRangeType}
            />
            <TextField
              label="Zone (optional)"
              value={rangeZone}
              onChange={setRangeZone}
              placeholder="Manhattan"
              autoComplete="off"
              helpText="Group these ZIP codes under a zone name."
            />
            <TextField
              label="Delivery Message (optional)"
              value={rangeMessage}
              onChange={setRangeMessage}
              placeholder="We deliver to your area!"
              autoComplete="off"
            />
            <TextField
              label="ETA (optional)"
              value={rangeEta}
              onChange={setRangeEta}
              placeholder="2-3 business days"
              autoComplete="off"
            />
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

