            style={{
              background: cfg.primaryColor,
              color: "#fff",
              border: "none",
              borderRadius: 50,
              padding: "12px 20px",
              fontSize: 13,
              fontWeight: 600,
              cursor: "pointer",
              boxShadow: `0 4px 16px ${cfg.primaryColor}40`,
