        where: { shop },
        create: { shop },
        update: resetData,
      });

      await syncConfigMetafield(admin, resetData);

      return { success: true, action: "reset" };
    }

    return null;
  } catch {
    return new Response(JSON.stringify({ error: "Failed to save widget settings." }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
