 86→      ? parseFloat(String(formData.get("deliveryFee")))
 87→      : null;
 88→    const freeShippingAbove = formData.get("freeShippingAbove")
 89→      ? parseFloat(String(formData.get("freeShippingAbove")))
 90→      : null;
 91→    const estimatedDays =
 92→      String(formData.get("estimatedDays") || "").trim() || null;
 93→    const cutoffTime =
 94→      String(formData.get("cutoffTime") || "").trim() || null;
 95→    const daysOfWeek =
 96→      String(formData.get("daysOfWeek") || "").trim() || null;
 97→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
 98→
 99→    if (!name) return { error: "Rule name is required." };
100→
101→    const data = {
102→      name,
103→      zone,
104→      zipCodes,
105→      minOrderAmount,
106→      deliveryFee,
107→      freeShippingAbove,
108→      estimatedDays,
109→      cutoffTime,
110→      daysOfWeek,
111→      priority,
112→    };
113→
114→    if (intent === "update" && id) {
115→      try {
116→        const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
117→        if (!existing) return { error: "Rule not found." };
118→        await db.deliveryRule.update({ where: { id }, data });
119→        return { success: true, action: "updated" };
120→      } catch {
121→        return { error: "Failed to update rule." };
122→      }
123→    } else {
124→      // Plan-gating: check limits before creating a new rule
125→      const subscription = await getShopSubscription(shop);
126→      const { maxDeliveryRules, label: planLabel } = subscription.limits;
127→
128→      if (maxDeliveryRules === 0) {
