140→          };
141→        }
142→      }
143→
144→      await db.deliveryRule.create({ data: { shop, ...data } });
145→      return { success: true, action: "created" };
146→    }
147→  }
148→
149→  if (intent === "delete") {
150→    const id = String(formData.get("id"));
151→    try {
152→      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
153→      if (!existing) return { error: "Rule not found." };
154→      await db.deliveryRule.delete({ where: { id } });
155→      return { success: true, action: "deleted" };
156→    } catch {
