424→    function normalizeZip(raw) {
425→      var z = raw.trim().toUpperCase();
426→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
427→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
428→      return z;
429→    }
430→
431→    function checkZip() {
432→      var zip = normalizeZip(inp.value);
433→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
434→      if (!zip) { inp.focus(); return; }
435→
436→      btn.disabled = true;
437→      btn.textContent = "\u2026";
438→      res.innerHTML = "";
439→
440→      fetch(
441→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
442→          "&zip=" + encodeURIComponent(zip)
443→      )
444→        .then(function (r) { return r.json(); })
