452→            sessionStorage.setItem('zcc:zip', zip);
453→            sessionStorage.setItem('zcc:shop', SHOP);
454→            // Fire custom event for other scripts to listen to
455→            window.dispatchEvent(new CustomEvent('zcc:validated', {
456→              detail: { valid: data.allowed, zip: zip }
457→            }));
458→          } catch(e) { /* sessionStorage may be unavailable */ }
459→
460→          // SVG icons for results
461→          var svgCheck = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><path d="M22 4L12 14.01l-3-3"/></svg>';
